private static server str orderedCasesComputed()
{
    return 'Floor(' + SysComputedColumn::divide(
           'abs(' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierStr(InventTransferLine),
            fieldStr(InventTransferLine, QtyTransfer)) + ')'
        ,
           'CASE ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
            fieldStr(METInventTransferLine, ShipCaseQty)) + ' WHEN 0 THEN 1 ELSE ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
            fieldStr(METInventTransferLine, ShipCaseQty)) + ' END'
        ) + ' )';
}

private static server str OrderedBrokenCasesComputed()
{
    return 'abs(' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierStr(InventTransferLine),
            fieldStr(InventTransferLine, QtyTransfer)) + ')'
            + ' % ' +
           'CASE ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
            fieldStr(METInventTransferLine, ShipCaseQty)) + ' WHEN 0 THEN 1 ELSE ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
            fieldStr(METInventTransferLine, ShipCaseQty)) + ' END';
}

private static server str actualBrokenCasesComputed()
{
    return 'abs(' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierStr(InventTrans),
            fieldStr(InventTrans, Qty)) + ')'
            + ' % ' +
           'CASE ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
            fieldStr(METInventTransferLine, ShipCaseQty)) + ' WHEN 0 THEN 1 ELSE ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
            fieldStr(METInventTransferLine, ShipCaseQty)) + ' END';
}

private static server str actualVolume()
{
    return METInventTransferLineActuals::actualCasesComputed() + ' * ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
        fieldStr(METInventTransferLine, TOUnitVolume));
}

private static server str actualWeight()
{
    return METInventTransferLineActuals::actualCasesComputed() + ' * ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
        fieldStr(METInventTransferLine, TOUnitWeight));
}

private static server str actualVolumeEA()
{
    return METInventTransferLineActuals::actualBrokenCasesComputed() + ' * ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
        fieldStr(METInventTransferLine, TOUnitVolumeEA));
}

private static server str actualWeightEA()
{
    return METInventTransferLineActuals::actualBrokenCasesComputed() + ' * ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventTransferLine),
