private static server str actualPalletVolume()
{
    return 'CASE ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventLocation),
        fieldStr(METInventLocation, WHSPalletVolume))
        + ' WHEN 0 THEN 0 ELSE ' +

        '( ' + METInventTransferLineActuals::actualVolumeEA() 
            + ' + ' + METInventTransferLineActuals::actualVolume()
            + ') / ' + SysComputedColumn::returnField(
            tableStr(METInventTransferLineActuals),
            identifierstr(METInventLocation),
        fieldStr(METInventLocation, WHSPalletVolume)) + ' END';
}
